166:  const local = new Map(current.map(r=>[r.id,r]));
167:  const paused = (row:RecipeChange, target:CustomerPackRecipe, revision:number) => {
168:    const saved=local.get(row.id);
169:    return !!saved && saved.revision===revision && saved.status==='shadow' && saved.schedule===null && saved.planApprovedAt===null && saved.approvedRevision===null && same(definition(saved),target);
170:  };
171:  if (change.recipes.every(r=>paused(r,r.after,r.revision===0 ? 1 : r.revision+1+(same(off(r.before!),r.after)?0:1)))) return 'after';
172:  if (change.recipes.every(r=>r.before===null ? !local.has(r.id) : paused(r,off(r.before),r.revision+1))) return 'paused';
173:  if (change.recipes.every(r=>r.before===null ? !local.has(r.id) : local.has(r.id)&&stamp(local.get(r.id)!)===r.beforeStamp)) return 'before';
